PRAGMA foreign_keys = ON;
CREATE TABLE Roles(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE Users(Id INTEGER PRIMARY KEY, Login TEXT NOT NULL UNIQUE COLLATE NOCASE, LastName TEXT NOT NULL, FirstName TEXT NOT NULL, MiddleName TEXT NOT NULL, RoleId INTEGER NOT NULL REFERENCES Roles(Id));
CREATE TABLE Categories(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE Subcategories(Id INTEGER PRIMARY KEY, CategoryId INTEGER NOT NULL REFERENCES Categories(Id), Name TEXT NOT NULL, UNIQUE(CategoryId, Name));
CREATE TABLE Manufacturers(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE Products(Id INTEGER PRIMARY KEY, SubcategoryId INTEGER NOT NULL REFERENCES Subcategories(Id), ManufacturerId INTEGER NOT NULL REFERENCES Manufacturers(Id), Name TEXT NOT NULL, Image TEXT NOT NULL, Description TEXT NOT NULL, Composition TEXT NOT NULL, PriceCents INTEGER NOT NULL CHECK(PriceCents>=0), UNIQUE(Name, ManufacturerId));
CREATE TABLE Sizes(Id INTEGER PRIMARY KEY, Value REAL NOT NULL UNIQUE CHECK(Value>0));
CREATE TABLE StockItems(Id INTEGER PRIMARY KEY, ProductId INTEGER NOT NULL REFERENCES Products(Id), SizeId INTEGER NOT NULL REFERENCES Sizes(Id), Quantity INTEGER NOT NULL CHECK(Quantity>=0), UNIQUE(ProductId, SizeId));
CREATE TABLE Orders(Id INTEGER PRIMARY KEY, OrderedAt TEXT NOT NULL CHECK(date(OrderedAt) IS NOT NULL), UserId INTEGER NOT NULL REFERENCES Users(Id));
CREATE TABLE OrderLines(Id INTEGER PRIMARY KEY, OrderId INTEGER NOT NULL REFERENCES Orders(Id) ON DELETE CASCADE, StockItemId INTEGER NOT NULL REFERENCES StockItems(Id), Quantity INTEGER NOT NULL CHECK(Quantity>0), UnitPriceCents INTEGER NOT NULL CHECK(UnitPriceCents>=0), UNIQUE(OrderId, StockItemId));
CREATE INDEX IX_Orders_OrderedAt ON Orders(OrderedAt);
CREATE INDEX IX_OrderLines_StockItemId ON OrderLines(StockItemId);
